octo.registerCommand("table-format", "Align Markdown tables", function (t) {
  var lines = String(t).split("\n"), out = [], i = 0;
  function isRow(s) { return /^\s*\|.*\|\s*$/.test(s); }
  function cells(s) {
    var r = s.replace(/^\s*\|/, "").replace(/\|\s*$/, "").split("|");
    for (var k = 0; k < r.length; k++) r[k] = r[k].replace(/^\s+|\s+$/g, "");
    return r;
  }
  function isSep(s) {
    var c = cells(s);
    if (c.length === 0) return false;
    for (var k = 0; k < c.length; k++) if (!/^:?-+:?$/.test(c[k])) return false;
    return true;
  }
  while (i < lines.length) {
    if (!isRow(lines[i])) { out.push(lines[i]); i++; continue; }
    var block = [];
    while (i < lines.length && isRow(lines[i])) { block.push(lines[i]); i++; }
    var rows = [], aligns = null;
    for (var b = 0; b < block.length; b++) {
      if (b === 1 && isSep(block[b])) { aligns = cells(block[b]); rows.push(null); }
      else rows.push(cells(block[b]));
    }
    var width = 0;
    for (var r0 = 0; r0 < rows.length; r0++) {
      if (rows[r0] && rows[r0].length > width) width = rows[r0].length;
    }
    var w = [];
    for (var c0 = 0; c0 < width; c0++) {
      var mx = 3;
      for (var r1 = 0; r1 < rows.length; r1++) {
        if (rows[r1] && rows[r1][c0] && rows[r1][c0].length > mx) mx = rows[r1][c0].length;
      }
      w.push(mx);
    }
    for (var r2 = 0; r2 < rows.length; r2++) {
      var outCells = [];
      for (var c1 = 0; c1 < width; c1++) {
        if (rows[r2] === null) {
          var a = (aligns && aligns[c1]) ? aligns[c1] : "---";
          var left = a.charAt(0) === ":", right = a.charAt(a.length - 1) === ":";
          var dash = w[c1] - (left ? 1 : 0) - (right ? 1 : 0);
          if (dash < 1) dash = 1;
          outCells.push((left ? ":" : "") + new Array(dash + 1).join("-") + (right ? ":" : ""));
        } else {
          var v = rows[r2][c1] || "";
          while (v.length < w[c1]) v += " ";
          outCells.push(v);
        }
      }
      out.push("| " + outCells.join(" | ") + " |");
    }
  }
  return out.join("\n");
});
